import { measure, measureFloor, NEAR_FLOOR_FACTOR } from '@abide/bench/measure'
import { createServerBenches } from '@abide/bench/serverBenches'
import { GET } from 'abide/server/GET'
import { jsonl } from 'abide/server/jsonl'

// LIVE SERVER-DISPATCH BENCH (server side).
//
// The other half of every request the frontend bench (`/platform/bench`) doesn't touch: the in-process
// per-request/per-read primitives on the hot path — route classification (`matchRoute`), cache-key
// building (`canonicalKey`), and the `memo` read/verb surface. Drives the SAME `@abide/bench/serverBenches`
// recipes the CLI runner (`packages/bench/server.ts`) does, timed with the SAME `@abide/bench/measure`
// loop, so the docs numbers and CLI numbers never drift. Streams one row at a time via `jsonl`, so the
// page fills its table live with `{#for await}`. Unlike the CLI runner this omits the end-to-end
// `createTestApp` dispatch benches — booting a real server per page-load is wrong for a live page; these
// primitives are the tight numbers the framework's per-request hot path is actually made of.
//
// A shorter-than-CLI budget keeps a page load snappy while still averaging over enough iterations.

export interface ServerBenchRow {
    group: string
    name: string
    note: string
    nsPerOp: number
    iters: number
    // The same work hand-written with no framework (`ServerBench.baseline`), timed by the same loop in
    // the same request — so `ratio` (abide ÷ vanilla) is a hardware-neutral figure.
    vanillaNsPerOp: number | null
    vanillaNote: string | null
    ratio: number | null
    // Either side is within `NEAR_FLOOR_FACTOR` of the timing loop's own per-iteration cost, which is
    // added to both — so the ratio is squashed toward 1.00× and understates the real one.
    nearFloor: boolean
}

const BUDGET = { minTimeMs: 100, minIters: 15, warmupIters: 5 }

export default GET(() => {
    async function* run(): AsyncIterable<ServerBenchRow> {
        const floor = await measureFloor(BUDGET)
        const limit = floor.nsPerOp * NEAR_FLOOR_FACTOR
        const benches = await createServerBenches()
        for (const bench of benches) {
            const metric = await measure(bench.run, BUDGET)
            const vanilla = bench.baseline ? await measure(bench.baseline.run, BUDGET) : null
            yield {
                group: bench.group,
                name: bench.name,
                note: bench.note,
                nsPerOp: metric.nsPerOp,
                iters: metric.iters,
                vanillaNsPerOp: vanilla?.nsPerOp ?? null,
                vanillaNote: bench.baseline?.note ?? null,
                ratio: vanilla ? metric.nsPerOp / vanilla.nsPerOp : null,
                nearFloor: vanilla !== null && (metric.nsPerOp < limit || vanilla.nsPerOp < limit),
            }
            await new Promise((resolve) => setTimeout(resolve, 40))
        }
    }
    return jsonl(run())
})

src/server/rpc/cacheCounter.ts:
import { GET } from 'abide/server/GET'

// A read RPC whose handler counts how many times it actually RAN, per `key`. The client-side memo
// proxy caches by args, so repeated reads reuse one result and `runs` stays put; `refresh` and
// `invalidate` force a re-fetch and the count climbs — the whole point of the cache demo, proven
// against a real isomorphic fetch (in-proc on the server, HTTP from the browser).
const runsByKey = new Map<string, number>()

export default GET(({ key = 'alpha' }) => {
    const next = (runsByKey.get(key) ?? 0) + 1
    runsByKey.set(key, next)
    return { key, runs: next }
})

src/server/rpc/cacheDebounced.ts:
import { GET } from 'abide/server/GET'

// The SWR refetch clock, debounce edge — the sibling of `cacheThrottled`. Debounce fires only AFTER
// quiet, and every trigger restarts the window, so the same five rapid `refresh()` calls cost ONE
// run where throttle costs two. Setting both edges on one memo is a construction-time error: they
// are two edges of one clock, not two clocks.
let runs = 0

export default GET(
    ({ tag = 'db' }) => {
        runs++
        return { tag, runs }
    },
    { memo: { debounce: 400 } },
)

src/server/rpc/cacheFlaky.ts:
import { error } from 'abide/server/error'
import { GET } from 'abide/server/GET'

// A read that fails on demand so the `error` probe can be exercised: `{ fail: true }` throws a 400
// (the client proxy decodes it back into the HttpError the `error` probe holds), otherwise it succeeds.
export default GET(({ fail = false }) => {
    if (fail) error(400, 'flaky boom')
    return { ok: true }
})

src/server/rpc/cacheMetric.ts:
import { GET } from 'abide/server/GET'

// A read keyed by the WHOLE args object `{ team, id }`. Each distinct pair is its own cache slot, so
// a partial selector like `invalidate({ team: "red" })` matches every superset slot (both red rows)
// and leaves blue alone. `runs` is a global monotonic counter so a re-fetch is always visible.
let runs = 0

export default GET(({ team, id }: { team: string; id: number }) => {
    runs++
    return { team, id, runs }
})

src/server/rpc/cacheOff.ts:
import { GET } from 'abide/server/GET'

// `memo: false` opts this read OUT of the memo entirely — every call runs the handler (no retain, no
// coalesced reuse, no client cache). The run counter climbs on EVERY read, on both sides.
let runs = 0
export default GET(() => ++runs, { memo: false })

src/server/rpc/cacheOn.ts:
import { GET } from 'abide/server/GET'

// The contrast: a DEFAULT read is memoed — the handler runs once and later reads reuse the retained
// value (the client never even re-fetches). The counter holds across reads.
let runs = 0
export default GET(() => ++runs)

