import { GET } from 'abide/server/GET'
import { request } from 'abide/server/request'
import { reachable } from 'abide/shared/reachable'

// Demonstrates `reachable(host)` from the isomorphic surface: probes the app's own origin (answers,
// so → true) and a dead local port (refused, so → false). Called from the browser via the RPC, it
// shows both branches of an active reachability probe without depending on the public internet.
export default GET(async () => {
    const origin = new URL(request().url).origin
    const self = await reachable(origin)
    const dead = await reachable('http://127.0.0.1:9')
    return { self, dead }
})

src/server/rpc/cacheShared.ts:
import { GET } from 'abide/server/GET'

// A SHARED read: its cache slot lives in the process-global shared store (not the per-request
// context), so the handler runs ONCE and every later request — any tab, any identity — is served
// the same retained value. `runs` counts real handler executions, so two separate HTTP requests
// (two `raw()` fetches) return the SAME count: proof of the cross-request cache. A shared handler is
// identity-independent and fail-closed — it runs scope-exited, so touching request scope would throw.
let runs = 0

export default GET(
    ({ tag = 's' }) => {
        runs++
        return { tag, runs }
    },
    { memo: { crossRequest: true } },
)

src/server/rpc/cacheSlow.ts:
import { GET } from 'abide/server/GET'

// A deliberately slow read so the `pending` probe (and a "refresh keeps the stale value visible"
// window) are observable in a real browser. Per-key run counter proves each re-fetch actually ran.
const runsByKey = new Map<string, number>()

export default GET(async ({ key = 'alpha' }) => {
    await Bun.sleep(500)
    const next = (runsByKey.get(key) ?? 0) + 1
    runsByKey.set(key, next)
    return { key, runs: next }
})

src/server/rpc/cacheTagA.ts:
import { GET } from 'abide/server/GET'

// A SHARED read tagged "docs". Declaring `tags` on a shared read registers this memo in the
// server-side tag registry, so the global `invalidate({ tags: ["docs"] })` / `refresh({ tags })`
// selectors act on it (and its sibling cacheTagB) together. `runs` counts real handler executions;
// the small delay makes the first-load `pending({ tags })` aggregate observable server-side.
let runs = 0

export default GET(
    async ({ tag = 'a' }) => {
        await Bun.sleep(150)
        runs++
        return { tag, runs }
    },
    { memo: { crossRequest: true, tags: ['docs'] } },
)

src/server/rpc/cacheTagB.ts:
import { GET } from 'abide/server/GET'

// The sibling of cacheTagA: a SHARED read carrying the same "docs" tag. One global
// `invalidate({ tags: ["docs"] })` drops BOTH memos' slots at once — the whole point of tags —
// so a later read of each re-runs its handler and `runs` climbs on both together.
let runs = 0

export default GET(
    async ({ tag = 'b' }) => {
        await Bun.sleep(150)
        runs++
        return { tag, runs }
    },
    { memo: { crossRequest: true, tags: ['docs'] } },
)

src/server/rpc/cacheTagBust.ts:
import { POST } from 'abide/server/POST'
import { invalidate } from 'abide/shared/invalidate'

// Drives the GLOBAL tag verb `invalidate({ tags })` — the only global cache-verb form. It is a
// SERVER concept: the tag registry is populated only by shared memos (server-side), so this runs in
// a mutation. One call drops every shared slot carrying the "docs" tag (both cacheTagA and cacheTagB)
// back to idle, so the next read of each re-runs its handler.
export default POST(() => {
    invalidate({ tags: ['docs'] })
    return { ok: true, verb: 'invalidate', tags: ['docs'] }
})

src/server/rpc/cacheTagPending.ts:
import { GET } from 'abide/server/GET'
import { invalidate } from 'abide/shared/invalidate'
import { pending } from 'abide/shared/pending'
import cacheTagA from '$server/rpc/cacheTagA'
import cacheTagB from '$server/rpc/cacheTagB'

// Surfaces the GLOBAL reactive aggregate `pending({ tags })` — true if ANY shared slot carrying a
// listed tag is on its first load. Exposed through a read so the transition can be observed
// deterministically — NOT because the registry is server-side; tags are isomorphic and register in the
// browser too. Deterministic: drop the tag's slots, kick a fresh load of each WITHOUT awaiting
// (so both are mid-first-load), then read the aggregate synchronously — it reports `true`.
export default GET(() => {
    invalidate({ tags: ['docs'] })
    void cacheTagA({ tag: 'a' })
    void cacheTagB({ tag: 'b' })
    return { pending: pending({ tags: ['docs'] }) }
})

src/server/rpc/cacheTagRefresh.ts:
import { POST } from 'abide/server/POST'
import { refresh } from 'abide/shared/refresh'

// Drives the GLOBAL tag verb `refresh({ tags })` — the eager sibling of `invalidate({ tags })`.
// Server-only (the tag registry lives server-side). One call eagerly revalidates every shared slot
// carrying the "docs" tag (both cacheTagA and cacheTagB), retaining each stale value while it
// re-runs — so a later read of each returns a freshly climbed `runs`.
export default POST(() => {
    refresh({ tags: ['docs'] })
    return { ok: true, verb: 'refresh', tags: ['docs'] }
})

src/server/rpc/cacheTagSlow.ts:
import { GET } from 'abide/server/GET'

// A slow, SHARED, TAGGED read — the subject of the global tag-probe demo. Being shared registers its
// slot in the server-only tag registry under "live", so the global `pending({ tags: ["live"] })` /
// `refreshing({ tags: ["live"] })` aggregates can observe it.
let runs = 0
export default GET(
    async () => {
        runs++
        await new Promise((resolve) => setTimeout(resolve, 200))
        return runs
    },
    { memo: { crossRequest: true, tags: ['live'] } },
)

src/server/rpc/cacheThrottled.ts:
import { GET } from 'abide/server/GET'

// The SWR refetch clock, throttle edge. `runs` counts real executions, so a burst of `refresh()`
// calls inside the window is observable as WORK rather than as a value: throttle fires on the
// LEADING edge and then collapses the rest of the window into ONE trailing load, so five rapid
// triggers cost two runs, not five.
//
// The clock is bilateral — the registry ships it to the browser proxy, so this is the CLIENT memo's
// clock the demo is driving, not the server's.
let runs = 0

export default GET(
    ({ tag = 'th' }) => {
        runs++
        return { tag, runs }
    },
    { memo: { throttle: 400 } },
)

src/server/rpc/cacheTtl.ts:
import { GET } from 'abide/server/GET'

// A SHARED read with a TTL: the process-global slot is served from cache until it is `ttl` ms old,
// then the next read re-runs the handler. `runs` counts real executions, so two `raw()` fetches
// inside the window return the SAME count, and a fetch after the window returns a HIGHER one —
// proof the value expired and re-fetched. TTL is enforced server-side (the client memo is untimed).
let runs = 0

export default GET(
    ({ tag = 't' }) => {
        runs++
        return { tag, runs }
    },
    { memo: { crossRequest: true, ttl: 700 } },
)

