src/server/rpc/platformConfig.ts:
// #demo platformConfig
import { env } from 'abide/server/env'
import { GET } from 'abide/server/GET'

// `env(schema)` reads typed, boot-validated config from the environment. Strings are coerced by the
// schema, defaults fill in missing keys, and the result is a frozen typed object. The result type is
// INFERRED from the schema (schema-first) — no `<T>` or `as {…}` to keep in sync: `config.DOCS_MAX_ITEMS`
// is `number`, `config.DOCS_FEATURE_MACHINES` is `boolean`, etc. Here every field has a default so the
// RPC is self-contained (no env vars required to boot).
export default GET(() => {
    const config = env({
        DOCS_APP_NAME: { type: 'string', default: 'abide docs' },
        DOCS_MAX_ITEMS: { type: 'number', default: 25 },
        DOCS_FEATURE_MACHINES: { type: 'boolean', default: true },
    })
    return {
        appName: config.DOCS_APP_NAME,
        maxItems: config.DOCS_MAX_ITEMS,
        featureMachines: config.DOCS_FEATURE_MACHINES,
        maxItemsType: typeof config.DOCS_MAX_ITEMS,
    }
})
// #enddemo

src/server/rpc/platformContext.ts:
// #demo platformContext
import { context } from 'abide/server/context'
import { GET } from 'abide/server/GET'

// `context()` is a per-request, free-form carrier bag. A per-RPC middleware writes into it; the handler
// beneath it in the onion reads it back — the hand-off from a middleware layer to the handler.
const stamp = (next: () => Response | Promise<Response>) => {
    context().stampedBy = 'platformContext.middleware'
    context().stampedAt = 2026
    return next()
}

export default GET(
    () => {
        const bag = context()
        return {
            stampedBy: typeof bag.stampedBy === 'string' ? bag.stampedBy : null,
            stampedAt: typeof bag.stampedAt === 'number' ? bag.stampedAt : null,
        }
    },
    { middleware: [stamp] },
)
// #enddemo

src/server/rpc/platformCookies.ts:
// #demo platformCookies
import { cookies } from 'abide/server/cookies'
import { GET } from 'abide/server/GET'

// `cookies()` returns the request's `Bun.CookieMap`. The browser sets `document.cookie`; this RPC reads
// it back server-side, so the value round-trips through the request scope.
export default GET(({ cookieName = 'platform_pref' }) => {
    const jar = cookies()
    return {
        cookieName,
        cookieValue: jar.get(cookieName) ?? null,
        cookieNames: Array.from(jar.keys()),
    }
})
// #enddemo

src/server/rpc/platformGuard.ts:
// #demo platformGuard
import { context } from 'abide/server/context'
import { error } from 'abide/server/error'
import { GET } from 'abide/server/GET'
import { request } from 'abide/server/request'

// The RPC middleware ONION, two layers deep. Each layer is `(next) => Response`; it owns the call to
// the layer beneath. `next()` runs the rest of the chain (and eventually the handler).

// Layer 1 — authorize. A read carries its args in the URL in EITHER documented form: the canonical
// `?__abide_args=<json>` blob a machine caller (the browser proxy) emits, or flat per-field params
// (`?allow=no`) for hand-testing. The reserved param is namespaced so it can never collide with a
// handler's own field. When `allow` is "no" this calls `error(403)` WITHOUT calling `next()` — and
// `error()` THROWS rather than returning a Response, which the chain renders at the status asked for.
// Either way it is a short-circuit: layer 2 and the handler never run.
const authorize = (next: () => Response | Promise<Response>) => {
    const params = new URL(request().url).searchParams
    // Flat form first as the default, then let the canonical blob win if present (same precedence the
    // router applies).
    let allow = params.get('allow') ?? 'yes'
    const raw = params.get('__abide_args')
    if (raw !== null) {
        try {
            const parsed = JSON.parse(raw) as { allow?: string }
            if (typeof parsed.allow === 'string') allow = parsed.allow
        } catch {
            // Malformed args — leave the default and let the handler's own validation handle it.
        }
    }
    if (allow === 'no') error(403, 'blocked by middleware')
    return next()
}

// Layer 2 — stamp. Reached only when layer 1 called `next()`. Records who let the request through
// into the per-request `context()` bag, then passes through to the handler.
const stamp = (next: () => Response | Promise<Response>) => {
    context().passedGuard = 'platformGuard.authorize'
    return next()
}

// The handler runs only for authorized requests; it reads back the stamp layer 2 left in context().
export default GET(
    ({ allow = 'yes' }) => {
        const bag = context()
        return {
            allow,
            passedGuard: typeof bag.passedGuard === 'string' ? bag.passedGuard : null,
        }
    },
    { middleware: [authorize, stamp] },
)
// #enddemo

src/server/rpc/platformHealth.ts:
// #demo platformHealth
import { GET } from 'abide/server/GET'
import { health } from 'abide/shared/health'

// `health()` is isomorphic AND symmetric in CONTENT: here on the server it composes the whole document
// in-proc — the framework baseline `{ reachable, version, startedAt, uptime }` with this app's
// `onHealth()` merged over it — while in the browser the same call awaits a fetch of `/__abide/health`.
// Same import, same call, same document.
//
// This handler also exists to make the TYPE load-bearing. `abide` generates `src/.abide/health.d.ts`
// from this app's `onHealth` return type, so `doc.bootId` below is a CHECKED read: it type-checks here
// and is a compile error in an app that declares no such hook. The two browser demos read the document
// through a `state(null)` cell, which the checker widens to `any` — so neither of them consults the
// generated companion, and neither can catch it regressing. This one can.
export default GET(async () => {
    const doc = await health()
    return { reachable: doc.reachable, app: doc.app, bootId: doc.bootId }
})
// #enddemo

src/server/rpc/platformIdentity.ts:
// #demo platformIdentity
import { GET } from 'abide/server/GET'
import { identity } from 'abide/shared/identity'

// Read the current request principal. `identity()` is ISOMORPHIC — this same import and call answers
// in a component too, where it returns the principal the SERVER resolved for the page (seeded at
// hydration, reactive, refreshed with `identity.refresh()`). It is never null on either side: the
// framework resolves an anonymous principal by default (via the bearer/cookie ladder) and a sealed
// authenticated one once `identity.set()` has run and the rolling `abide-identity` cookie rides
// subsequent requests. Only the WRITES are server-side — a browser cannot seal a cookie, so
// `identity.set()` there throws and names the mutation to call instead.
export default GET(() => {
    const principal = identity()
    return {
        id: principal.id,
        authenticated: principal.authenticated,
        name: typeof principal.name === 'string' ? principal.name : null,
    }
})
// #enddemo

src/server/rpc/platformLog.ts:
// #demo platformLog
import { GET } from 'abide/server/GET'
import { log } from 'abide/shared/log'

// `log` is isomorphic structured logging. Every line is labeled with a CHANNEL. The bare `log(...)`
// (and `.info` / `.warn` / `.error` / `.trace`) uses the DEFAULT channel — the app name ("docs" here,
// from package.json) — and is ALWAYS ON. `log.channel(name)` names a channel gated by the `DEBUG` env
// var (debug-npm style: `DEBUG=docs:cards` or `DEBUG=*`; the browser reads `localStorage.debug`). A
// BARE name is namespaced under the app for you — `channel('cards')` labels and gates as
// `docs:cards` — so framework internals (`abide:*`) and verbose app channels stay quiet until asked
// for, and `DEBUG=docs:*` asks for all of this app's. One exception: `error` always emits, even on a
// gated channel. These lines land on the SERVER console here, so the RPC returns the FACT that it
// logged for the UI to show.
export default GET(({ message = 'hello from the docs' }) => {
    log.info('card log (info)', { message }) // default "docs" channel — always on
    log.channel('cards').trace('verbose card detail', { message }) // gated: DEBUG=docs:cards
    return {
        logged: true,
        channel: 'docs',
        gated: 'docs:cards',
        levels: ['info', 'trace'],
        message,
    }
})
// #enddemo

src/server/rpc/platformLogin.ts:
// #demo platformLogin

import { POST } from 'abide/server/POST'
import { identity } from 'abide/shared/identity'

// A login mutation: `identity.set()` promotes the request principal to authenticated and marks the
// scope so the router seals a rolling `abide-identity` cookie onto the response. The next request
// from this browser carries that cookie, so `platformIdentity` then reads back an authenticated
// principal — the page reflects the logged-in state.
export default POST(({ name = 'anonymous' }) => {
    identity.set({ name })
    const principal = identity()
    return {
        id: principal.id,
        authenticated: principal.authenticated,
        name: typeof principal.name === 'string' ? principal.name : null,
    }
})
// #enddemo

src/server/rpc/platformLogout.ts:
// #demo platformLogout

import { POST } from 'abide/server/POST'
import { identity } from 'abide/shared/identity'

// The inverse of login: `identity.clear()` reverts to a fresh anonymous principal and marks the
// scope so the router clears the `abide-identity` cookie. Subsequent reads see anonymous again.
export default POST(() => {
    identity.clear()
    const principal = identity()
    return {
        id: principal.id,
        authenticated: principal.authenticated,
        name: typeof principal.name === 'string' ? principal.name : null,
    }
})
// #enddemo

src/server/rpc/platformObserve.ts:
// #demo platformObserve
import { GET } from 'abide/server/GET'
import { trace } from 'abide/shared/trace'

// `trace()` returns the request's W3C traceparent — seeded from an incoming header or lazily
// generated and cached on the request scope. A traceparent is `version-traceid-spanid-flags`; this
// read also splits out the trace id for display. (`health()` and `log()` each have their own card.)
export default GET(() => {
    const traceparent = trace()
    return {
        traceparent: traceparent ?? null,
        traceId: traceparent ? (traceparent.split('-')[1] ?? null) : null,
    }
