src/server/rpc/rpcBoom.ts:
import { error } from 'abide/server/error'
import { POST } from 'abide/server/POST'

// A mutating RPC that fails with a plain `error(status, message)`. `error()` THROWS an HttpError — that
// is what puts the failure in the memo slot's error channel instead of its value channel — and the
// router renders it at 422. Called from the browser it arrives as the same HttpError, so the caller
// catches it and reads status/message either side of the wire. The success branch still types as
// `{ ok: boolean }`: a `throw` is `never`, and a union absorbs it.
export default POST(({ ok = false }) => {
    if (ok) return { ok: true }
    error(422, 'note text is required')
})

src/server/rpc/rpcBumpCounter.ts:
import { POST } from 'abide/server/POST'

// A CACHED mutation. `memo: { ttl }` opts this POST into retention, so it gains the full read surface
// on the client: a repeat call within the ttl HITS the cache (handler not re-run), `.peek(args)` returns
// the retained value, and `.refresh(args)` re-runs the handler (`.refreshing(args)` is true meanwhile).
// The module `runs` counter makes each real execution observable — a cache hit keeps the number, a
// refresh bumps it. Default mutations are `ttl: 0` (retain nothing); this one opts in.
let runs = 0
export default POST(
    ({ id = 'counter' }) => {
        runs++
        return { id, runs }
    },
    { memo: { ttl: 60_000 } },
)

src/server/rpc/rpcCreateNote.ts:
import { POST } from 'abide/server/POST'

// A mutating RPC (POST). Mutations default to no retention (ttl:0) — each browser call runs the handler
// and returns its value; opt into caching with a `cache` TTL. Args ride in the JSON body (the
// content-type also satisfies the CSRF gate).
export default POST(({ text = '' }) => ({
    id: `note_${text.length}_${text.trim().slice(0, 8)}`,
    text,
    verb: 'POST',
    created: true,
}))

src/server/rpc/rpcDeleteNote.ts:
import { DELETE } from 'abide/server/DELETE'

// A mutating RPC (DELETE).
export default DELETE(({ id = '' }) => ({
    id,
    verb: 'DELETE',
    deleted: true,
}))

src/server/rpc/rpcEvents.ts:
import { GET } from 'abide/server/GET'
import { sse } from 'abide/server/sse'

// A streaming read over Server-Sent Events. The handler returns an `sse` Response (each item becomes a
// `data: <json>\n\n` frame); the browser reads the `text/event-stream` and renders frames as they land.
export default GET(({ count = 3 }) => {
    async function* events(): AsyncIterable<{ seq: number; kind: string }> {
        for (let seq = 1; seq <= count; seq++) {
            await new Promise((resolve) => setTimeout(resolve, 25))
            yield { seq, kind: seq === count ? 'final' : 'progress' }
        }
    }
    return sse(events())
})

src/server/rpc/rpcGoHome.ts:
import { GET } from 'abide/server/GET'
import { redirect } from 'abide/server/redirect'

// A read RPC that returns a `redirect` Response. The wire carries `302 Found` + `Location` (curl -i
// shows it); a browser fetch either FOLLOWS it — which is what the redirect demo observes, via
// `response.redirected` and the final `url` — or, with `redirect: "manual"`, resolves to an opaque
// response that withholds the status and headers from JS. Both are shown on /rpc/responses.
export default GET(({ to = '/rpc' }) => redirect(to, 302))

src/server/rpc/rpcGreet.ts:
import { GET } from 'abide/server/GET'

// A read RPC used across the rpc-bucket pages to demonstrate the async-read template forms
// ({fn()}, {await fn()}, {fn.peek()}, {#await}) and the raw-fetch bypass. Returns a plain value;
// the router serializes it with json(), so the same call is cached in-proc on SSR and a fetch in
// the browser.
export default GET(({ name = 'world' }) => ({
    greeting: `Hello, ${name}!`,
    length: name.length,
    at: new Date(2026, 0, 1).toISOString(),
}))

src/server/rpc/rpcGreetSlow.ts:
import { error } from 'abide/server/error'
import { GET } from 'abide/server/GET'

// The `{#await}` demo's read — deliberately SLOW, and failing on demand.
//
// It has its own file because the block it demonstrates has three branches and a fast read can only
// ever show one of them. `rpcGreet` settles in-proc in microseconds, well inside the 4ms SSR streaming
// deadline, so a `{#await}` over it renders `{:then}` INLINE: the pending branch never paints and the
// catch branch is unreachable. Making `rpcGreet` itself slow was not an option — eight other demos
// read it and would all have paid for this one.
//
// 400ms clears the deadline with a wide margin, so the pending branch really does render into the
// shell and the value arrives as an out-of-order patch; `fail: true` is a different memo slot, which
// is what lets the demo drive the third branch without a second RPC.
export default GET(async ({ name = 'world', fail = false }) => {
    await Bun.sleep(400)
    if (fail) error(503, 'the greeting service is unreachable')
    return { greeting: `Hello, ${name}!`, length: name.length }
})

src/server/rpc/rpcLimited.ts:
import { error } from 'abide/server/error'
import { POST } from 'abide/server/POST'

// A mutating RPC returning a NAMED, narrowable typed error. `error.typed(name, status)` builds a
// factory whose body carries the type name + payload; the browser catches it as an HttpError whose
// `kind` is the type name, so callers can narrow the failure ("RateLimited") from any other error.
const rateLimited = error.typed('RateLimited', 429)

export default POST(({ tokens = 0 }) => {
    if (tokens > 0) return { ok: true, tokens }
    return rateLimited({ retryAfter: 30 })
})

src/server/rpc/rpcPatchNote.ts:
import { PATCH } from 'abide/server/PATCH'

// A mutating RPC (PATCH) — partial update semantics.
export default PATCH(({ id = '', text = '' }) => ({
    id,
    text,
    verb: 'PATCH',
    patched: true,
}))

src/server/rpc/rpcPing.ts:
import { GET } from 'abide/server/GET'

// An ordinary read. There is no `HEAD` helper (ADR 0027 D6) — HTTP `HEAD` IS `GET` minus the body, so
// the router derives it: a HEAD request reaches THIS handler and the body is dropped. The demo fetches
// it with a raw `method: "HEAD"` to show exactly that — a 200 status line, headers only, no second
// declaration anywhere.
export default GET((): { ok: boolean } => ({ ok: true }))

src/server/rpc/rpcReplaceNote.ts:
import { PUT } from 'abide/server/PUT'

// A mutating RPC (PUT) — full replacement semantics. Same call surface as POST from the browser.
export default PUT(({ id = '', text = '' }) => ({
    id,
    text,
    verb: 'PUT',
    replaced: true,
}))

src/server/rpc/rpcStreamJob.ts:
import { jsonl } from 'abide/server/jsonl'
import { POST } from 'abide/server/POST'

// A STREAMING mutation. A POST handler that yields an `AsyncIterable` is stored as a ReplayableStream
// exactly like a streaming read and re-encoded as `application/jsonl`. The browser proxy decodes it back
// into an `AsyncIterable`, so `{#for await step of rpcStreamJob(...)}` works identically to a streaming
// read — full read/mutation symmetry for streams. Args ride in the JSON body (which also passes CSRF).
export default POST(({ steps = 3 }) => {
    async function* run(): AsyncIterable<{ step: number; label: string }> {
        for (let step = 1; step <= steps; step++) {
            await new Promise((resolve) => setTimeout(resolve, 25))
            yield { step, label: `step ${step} of ${steps} done` }
        }
    }
    return jsonl(run())
})

src/server/rpc/rpcTicker.ts:
import { GET } from 'abide/server/GET'
import { jsonl } from 'abide/server/jsonl'

// A streaming read: `jsonl(ticks())` sees through to the generator, so the memo stores a ReplayableStream
// (concurrent/late viewers share ONE run; retained per `cache.ttl`). The router re-encodes it as
// `application/jsonl`, which the browser consumes and renders line-by-line with `{#for await}`.
export default GET(({ count = 4 }) => {
    async function* ticks(): AsyncIterable<{ n: number; label: string }> {
        for (let n = 1; n <= count; n++) {
            await new Promise((resolve) => setTimeout(resolve, 25))
            yield { n, label: `tick ${n} of ${count}` }
        }
    }
    return jsonl(ticks())
})

src/server/rpc/rpcUpload.ts:
import { POST } from 'abide/server/POST'

// A multipart file-upload mutation (TODO #8). The single positional argument is the raw `FormData`:
// the `avatar` File rides in the body (never in a JSON args object). Two schemas guard it — `files`
// validates the uploaded FILE field (present, size, MIME), and the JSON `input` schema validates the
// multipart TEXT field `caption` (required, non-empty). Either failure surfaces as one 422 the client
// narrows to a ValidationError. The handler still receives the raw FormData and reads fields back out.
export default POST(
    async (form: FormData) => {
        const file = form.get('avatar')
        const caption = String(form.get('caption') ?? '')
        if (!(file instanceof File)) return { ok: false as const }
        return { ok: true as const, name: file.name, size: file.size, type: file.type, caption }
    },
    {
        schemas: {
            input: {
                type: 'object',
                properties: { caption: { type: 'string', minLength: 1 } },
                required: ['caption'],
            },
            files: {
                required: ['avatar'],
                properties: { avatar: { maxSize: 1_000_000, accept: 'text/*' } },
            },
        },
    },
)

src/server/rpc/serverReactiveBump.ts:
import { POST } from 'abide/server/POST'
import { doubled, total, watchFires } from '$shared/serverReactive'

// A DIFFERENT server module imports the shared `state` and writes it. The write propagates through the
// derived `doubled` and fires the `watch` back in serverReactive.ts — cross-module server reactivity.
// Returns the fresh snapshot (a mutation's return is authoritative and uncached).
export default POST(({ by = 1 }: { by?: number }) => {
    total.set(total.untracked() + by)
    return { total: total.untracked(), doubled: doubled.peek(), fires: watchFires() }
})

src/server/rpc/serverReactiveRead.ts:
import { GET } from 'abide/server/GET'
import { doubled, total, watchFires } from '$shared/serverReactive'

// Reads the current server-side graph: the source `state`, its derived `memo`, and the `watch`
// fire-count. `memo: false` so every read reflects the live values (this is reactive state, not a
// memoized fetch).
export default GET(
    () => ({ total: total.untracked(), doubled: doubled.peek(), fires: watchFires() }),
    {
        memo: false,
    },
)

src/server/rpc/snippet.ts:
import { relative, resolve, sep } from 'node:path'
import { error } from 'abide/server/error'
import { GET } from 'abide/server/GET'
import { codeBlock } from '$ui/lib/codeBlock'
import EMBEDDED_SOURCES from '../EMBEDDED_SOURCES.json'

// Reads a docs source file and extracts the region between demo markers, so a docs page can show the
// REAL demonstrated code (DRY — the snippet is the running source, never a hand-copied duplicate).
// Two marker syntaxes are supported so both `.ts` and `.abide` template regions can be marked:
//   TypeScript:  `// #demo <marker>` … `// #enddemo`
//   Template:    `<!-- #demo <marker> -->` … `<!-- #enddemo -->`
// The extracted region is dedented (common leading indentation stripped) and returned with a `lang`
// hint plus `html` — the server-rendered, syntax-highlighted `<pre class="code">` block. Highlighting
// runs here on the server (never in the browser); a page just injects `html` via `{html(...)}`.
// Path-traversal guarded: only files under docs/src resolve.

const DOCS_ROOT = resolve(import.meta.dir, '../../..')
const SRC_DIR = resolve(DOCS_ROOT, 'src')

// Read the demonstrated file. On disk normally — so a running `abide dev`/`start` always shows the
// CURRENT source, which is the whole point of reading it rather than copying it. Inside an `abide
// compile` binary there is no disk to read (`import.meta.dir` is `/$bunfs/root`, and the project was
// never copied to the deploy machine), so fall back to the map `scripts/embedSources.ts` baked in at
// compile time. `undefined` = neither has it, which the caller reports as a 404 rather than a 500.
const EMBEDDED: Record<string, string> = EMBEDDED_SOURCES

async function readSource(target: string): Promise<string | undefined> {
    const file = Bun.file(target)
    if (await file.exists()) return await file.text()
    return EMBEDDED[relative(DOCS_ROOT, target)]
}

function langForFile(file: string): string {
    if (file.endsWith('.abide')) return 'abide'
    if (file.endsWith('.ts') || file.endsWith('.tsx')) return 'ts'
    if (file.endsWith('.js') || file.endsWith('.jsx')) return 'js'
    return 'text'
}

// Strips the smallest common leading indentation across non-blank lines, then trims blank edges.
function dedent(lines: string[]): string {
    let common = Infinity
    for (const line of lines) {
        if (line.trim() === '') continue
        const indent = line.length - line.trimStart().length
        if (indent < common) common = indent
    }
    if (common === Infinity) common = 0
    const trimmed: string[] = []
    for (const line of lines) trimmed.push(line.slice(common))
    return trimmed.join('\n').trim()
}

const START = /^\s*(?:\/\/|<!--)\s*#demo\s+(\S+)/
const END = /^\s*(?:\/\/|<!--)\s*#enddemo\b/

export default GET(async ({ file, marker }: { file: string; marker?: string }) => {
    const target = resolve(DOCS_ROOT, file)
    if (target !== SRC_DIR && !target.startsWith(SRC_DIR + sep)) {
        return error(400, 'file must resolve under src/')
    }
    const source = await readSource(target)
    if (source === undefined) return error(404, `no such source file: ${file}`)
    const lang = langForFile(file)

    // No marker → return the WHOLE file (used for server RPC/socket source: the file IS the sample).
    if (marker === undefined || marker === '') {
        const code = source.replace(/\s+$/, '')
        return { code, lang, html: codeBlock(code, lang) }
    }

    const lines = source.split('\n')
    const region: string[] = []
    let capturing = false
    for (const line of lines) {
        if (!capturing) {
            const open = line.match(START)
            if (open !== null && open[1] === marker) capturing = true
            continue
        }
        if (END.test(line)) {
            const code = dedent(region)
            return { code, lang, html: codeBlock(code, lang) }
        }
        region.push(line)
    }
    return error(404, `demo marker "${marker}" not found in ${file}`)
})

src/server/rpc/socketsPublish.ts:
import { POST } from 'abide/server/POST'
import socketsChat, { type ChatMessage } from '$server/sockets/socketsChat'

// A mutating RPC that publishes to the chat socket from the SERVER. `socket.publish` bypasses the
// socket handler (unlike a client publish), so the message keeps `via: "server"`. Every live
// subscriber — the browser's SSE/WS subscription — receives it live and fans it into the DOM.
// #demo publish-rpc
export default POST(({ text }: { text: string }): { published: ChatMessage } => {
    const message: ChatMessage = {
        id: crypto.randomUUID(),
        text: String(text ?? '').trim() || '(empty)',
        via: 'server',
    }
    socketsChat.publish(message)
    return { published: message }
})
// #enddemo

src/server/rpc/streamBoom.ts:
import { GET } from 'abide/server/GET'

// A slow read that REJECTS — pairs with a `{#await}{:catch}` to show that a streamed subtree which
// errors after the shell flushed streams its `{:catch}` branch as the patch (streaming-ssr-plan PR5),
// and the client hydrates that catch branch in place. The declared return type keeps the output schema
// representable even though the handler always throws.
export default GET(async (): Promise<{ ok: boolean }> => {
    await Bun.sleep(120)
    throw new Error('stream boom — the read rejected')
})

src/server/rpc/streamBranch.ts:
import { GET } from 'abide/server/GET'

// A second slow SERVER read, identical in shape to `streamSlow` but with its own memo slot, used by the
// streaming block that sits inside an `{#if}` branch on `/pages/ssr`.
//
// It needs its own slot precisely because sharing one would defeat the test: two blocks awaiting the
// same coalesced promise cannot show that the BRANCH arm kept its own render frame.
let runs = 0

export default GET(async () => {
    await Bun.sleep(120)
    runs += 1
    return { runs }
})

src/server/rpc/streamSlow.ts:
import { GET } from 'abide/server/GET'

// A deliberately slow SERVER read so a `{#await}` block MISSES the SSR streaming deadline (4ms) and
// streams as an out-of-order patch (streaming-ssr-plan PR2/PR3) instead of rendering inline. The run
// counter increments on every (re-)fetch, so the e2e can prove the CLAIMED await block stays reactive
// after hydration — a refresh re-fetches and re-renders the streamed subtree in place.
let runs = 0

export default GET(async () => {
    await Bun.sleep(120)
    runs += 1
    return { runs }
})

src/server/rpc/tagProbes.ts:
import { GET } from 'abide/server/GET'
import { pending } from 'abide/shared/pending'
import { refreshing } from 'abide/shared/refreshing'
import cacheTagSlow from './cacheTagSlow'

// The GLOBAL tag PROBES — reactive aggregates: true if ANY slot carrying the tag is pending /
// refreshing. Exposed through a READ here because this handler captures both transitions in one
// deterministic pass — not because the probes are server-only. They are not: tags stopped requiring
// `crossRequest` and are isomorphic, so a tagged read's BROWSER memo registers too and these
// aggregates answer on both sides. A slot goes pending SYNCHRONOUSLY when its load starts, and
// refreshing when it revalidates over a retained value.
export default GET(
    async () => {
        cacheTagSlow.invalidate() // drop any retained slot
        const load = cacheTagSlow() // kick a fresh load (no await) → the slot goes pending now
        const pendingDuringLoad = pending({ tags: ['live'] })
        await load // let the first load settle → value retained
        const pendingAfterLoad = pending({ tags: ['live'] })

        cacheTagSlow.refresh() // revalidate over the retained value → refreshing now
        const refreshingDuringRefresh = refreshing({ tags: ['live'] })
        await cacheTagSlow() // coalesce onto the in-flight refresh, await settle
        const refreshingAfterRefresh = refreshing({ tags: ['live'] })

        return {
            pendingDuringLoad,
            pendingAfterLoad,
            refreshingDuringRefresh,
            refreshingAfterRefresh,
        }
    },
    { memo: false },
)

src/server/sockets/socketsChat.ts:
import { socket } from 'abide/server/socket'

export interface ChatMessage {
    id: string
    text: string
    via: string
}

// The demo chat socket — an isomorphic pub/sub topic. `tail` replays the last N messages to every new
// subscriber (so a page reload re-sees recent history); the `clientPublish` FUNCTION opens the two client
// publish paths (the HTTP face POST and the WS-mux `pub` frame) AND mediates every *client* publish (a
// server `publish` bypasses it) — here it stamps a fresh id + `via: "client"` and drops empty messages by
// returning `undefined`. The mediator's presence IS the permission (ADR 0023).
// #demo socket-def
export default socket<ChatMessage>({
    // The pub/sub knobs are the CHANNEL's own, nested rather than flattened (ADR 0027 D1) — a socket
    // adds transport and authorization, not vocabulary.
    channel: { tail: 20 },
    clientPublish: (message) => {
        const text = message && typeof message.text === 'string' ? message.text.trim() : ''
        if (text.length === 0) return
        return { id: crypto.randomUUID(), text, via: 'client' }
    },
})
// #enddemo

src/server/sockets/socketsPulse.ts:
import { socket } from 'abide/server/socket'

// A standalone topic owned solely by the done() probe demo. Because no other demo touches it, its
// client proxy starts IDLE — so `done()` genuinely reads `true` until the demo opens a subscription.
// (The shared chat topic is already live from the peek/chunks demos, which would mask the idle state.)
// #demo socket-pulse
export default socket<{ tick: number }>({ channel: { tail: 4 } })
// #enddemo

src/shared/serverReactive.ts:
import { memo } from 'abide/shared/memo'
import { state } from 'abide/shared/state'
import { watch } from 'abide/shared/watch'

// An isomorphic reactive value owned by the SERVER, living in a shared module — the SAME `state()`
// primitive UI components use, here running in plain server `.ts`. Other server modules import `total`,
// derive from it, and subscribe to it: a server-side reactive graph, no client involved.
//
// NOTE the explicit `total()` / `total.set(...)` calls below. In a `.abide` `<script>` you write bare
// `total` / `total = x` and the compiler rewrites those to `total()` / `total.set(x)` for you.
// There is no compiler here — plain `.ts` — so you call the `State` surface yourself:
//   total()           // tracked read (subscribes the surrounding memo/watch)
//   total.set(next)   // publish a new value
//   total.untracked() // untracked read (no subscription)
//
// It is `untracked()`, not `peek()`, because `peek` means the OPPOSITE on the other two primitives:
// `memo.peek(args)` / `channel.peek(args)` SUBSCRIBE and return `T | undefined` (ADR 0027 D2). Both
// spellings appear side by side one file over, in `serverReactiveRead.ts`.
//
// Module-level state is PROCESS-GLOBAL (one value across all requests) — fine for this global counter;
// for mutable per-request/per-user state, use `memo({ crossRequest })` instead.
export const total = state(0)

// A derived value in the same module — recomputes off `total` on read. An argless `memo` declares no
// inputs, so they are inferred from the body (ADR 0024): calling `total()` inside it is what wires the
// dependency, and the bare call `doubled()` returns the value, not a promise.
export const doubled = memo(() => total() * 2)

// A live server-side subscription: this `watch` fires whenever `total` changes, from ANY module that
// writes it — proof the graph is reactive on the server, not just recompute-on-read.
let fires = 0
watch(
    () => total(),
    () => {
        fires++
    },
)
export function watchFires(): number {
    return fires
}

src/ui/app.css:
/* abide docs — design system.
   Loaded once via the root layout; bundled + served as a content-hashed /__abide/chunk/style-<hash>.css.

   RHYTHM: all spacing (padding, gaps), type sizes, radii, and layout widths come from the scales in
   `:root` below. Stacking is done with flex/grid `gap` on the CONTAINER, never per-child margins, so the
   vertical rhythm is uniform and nothing bumps together. */

@import "tailwindcss";

/* FONTS — self-hosted from `src/ui/public/fonts/`, served same-origin at those literal paths.
   Previously a `@import url(fonts.googleapis.com/css2?…)`, which cost a THREE-STEP serial chain on a
   cold load: this stylesheet had to download and parse before the Google URL was even discovered, then
   that CSS had to download and parse before the .woff2 URLs were, then those were fetched cross-origin
   (fresh DNS + TLS, no preconnect). Measured ~2.1s to load with ~1.8s of continuous re-layout, against
   478ms warm — the fonts were the whole delta.

   The url()s are ROOT-ABSOLUTE on purpose. A relative one would be resolved by Bun's CSS bundler and
   inlined as a base64 data URL (at any size — there is no threshold, and `loader` does not apply to CSS
   references), pushing ~102KB of font, +33% for base64, into this render-blocking stylesheet. The
   absolute form is passed through instead, because `src/ui/public/`'s top-level entries are marked
   external for the client build.

   One file per family, not one per weight: these are VARIABLE fonts, so all the weights the docs use
   come out of a single face declared with a weight RANGE. That is also what the Google CSS was doing —
   its 55 @font-face rules resolved to just 3 distinct URLs. Latin subset only; the docs are English. */
@font-face {
    font-family: "Inter";
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
    src: url("/fonts/inter-latin-var.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC,
        U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215,
        U+FEFF, U+FFFD;
}

@font-face {
    font-family: "JetBrains Mono";
    font-style: normal;
    font-weight: 100 800;
    font-display: swap;
    src: url("/fonts/jetbrains-mono-latin-var.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC,
        U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215,
        U+FEFF, U+FFFD;
}

@font-face {
    font-family: "Space Grotesk";
    font-style: normal;
    font-weight: 300 700;
    font-display: swap;
    src: url("/fonts/space-grotesk-latin-var.woff2") format("woff2");
    unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC,
        U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215,
        U+FEFF, U+FFFD;
}

/* Scan the `.abide` templates for utility class usage — the emitted client modules live in a tmpdir,
   so this must point at the real source tree (../ = src/). */
@source "../**/*.abide";

/* Design tokens exposed to Tailwind utilities (bg-ink, text-signal, font-display, …). The palette is
   deliberately cool + precise — abide is infrastructure ("remain, endure"), not a warm editorial site.
   `signal` = the electric blue of a reactive read; `live` = the green of a settled/streaming memo. */
@theme {
    --color-ink: #0e1420;
    --color-ink-2: #161f2e;
    --color-ink-line: #26324a;
    --color-paper: #f4f6f9;
    --color-surface: #ffffff;
    --color-line: #e3e7ee;
    --color-text: #1a2431;
    --color-muted: #5c6b7f;
    --color-signal: #345bff;
    --color-signal-soft: #eaefff;
    --color-live: #12b886;

    --font-display: "Space Grotesk", ui-sans-serif, system-ui, sans-serif;
    --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
    --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
}

/* ── Scales — the single source of rhythm ─────────────────────────────────── */
:root {
    /* Spacing (4px base). Every padding + gap + width snaps to one of these. */
    --space-1: 0.25rem;
    /*  4 */
    --space-2: 0.5rem;
    /*  8 */
    --space-3: 0.75rem;
    /* 12 */
    --space-4: 1rem;
    /* 16 */
    --space-5: 1.25rem;
    /* 20 */
    --space-6: 1.5rem;
    /* 24 */
    --space-7: 2rem;
    /* 32 */
    --space-8: 2.5rem;
    /* 40 */
    --space-9: 3rem;
    /* 48 */
    --space-10: 4rem;
    /* 64 */
    --space-11: 5rem;
    /* 80 */

    /* Type scale (~1.2 ratio, 15px base) + line-heights. */
    --text-2xs: 0.6875rem;
    --text-xs: 0.75rem;
    --text-sm: 0.8125rem;
    --text-base: 0.9375rem;
    --text-lg: 1.125rem;
    --text-xl: 1.375rem;
    --text-2xl: 1.75rem;
    --text-3xl: clamp(1.9rem, 1.4rem + 2vw, 2.6rem);
    --leading-tight: 1.2;
    --leading-snug: 1.4;
    --leading-normal: 1.6;
    --leading-code: 1.55;

    /* Radii. */
    --radius-1: 6px;
    --radius-2: 8px;
    --radius-3: 10px;
    --radius-4: 12px;
    --radius-5: 14px;
    --radius-pill: 999px;

    /* Layout widths (same scale family — rem multiples of the shell). */
    --w-sidebar: 17rem;
    --w-cards: 54rem;
    /* the demo column — wide enough for two code measures side by side */
    --w-aside: 21rem;
    /* the prose column beside it */
    --w-content: 50rem;
    --w-prose: 40rem;
    --w-card-min: 14rem;
}

/* ── Base ─────────────────────────────────────────────────────────────────── */
@layer base {
    html {
        -webkit-text-size-adjust: 100%;
        scroll-behavior: smooth;
    }

    body {
        margin: 0;
        background: var(--color-paper);
        color: var(--color-text);
        font-family: var(--font-sans);
        font-size: var(--text-base);
        line-height: var(--leading-normal);
        -webkit-font-smoothing: antialiased;
    }

    /* Flow elements carry NO margin — their container's `gap` owns the rhythm. */
    h1,
    h2,
    h3,
    h4,
    p,
    ul,
    ol,
    figure,
    pre {
        margin: 0;
    }

    h1,
    h2,
    h3,
    h4 {
        font-family: var(--font-display);
        color: #0f1a2b;
        letter-spacing: -0.02em;
        line-height: var(--leading-tight);
    }

    h1 {
        font-size: var(--text-3xl);
        font-weight: 700;
    }

    h2 {
        font-size: var(--text-xl);
        font-weight: 600;
    }

    h3 {
        font-size: var(--text-lg);
        font-weight: 600;
    }

    a {
        color: var(--color-signal);
        text-decoration: none;
    }

    a:hover {
        text-decoration: underline;
        text-underline-offset: 2px;
    }

    ul,
    ol {
        padding-left: var(--space-5);
        display: flex;
        flex-direction: column;
        gap: var(--space-1);
    }

    :not(pre)>code {
        font-family: var(--font-mono);
        font-size: 0.86em;
        background: #eef1f6;
        color: #243247;
        padding: 0.12em 0.4em;
        border-radius: var(--radius-1);
        border: 1px solid #e2e7ef;
    }

    button {
        font: inherit;
        cursor: pointer;
        border: 1px solid var(--color-signal);
        background: var(--color-signal);
        color: #fff;
        padding: var(--space-2) var(--space-4);
        border-radius: var(--radius-2);
        font-weight: 500;
        transition: filter 0.12s ease, transform 0.06s ease;
    }

    button:hover {
        filter: brightness(1.06);
    }

    button:active {
        transform: translateY(1px);
    }

    input,
    select,
    textarea {
        font: inherit;
        padding: var(--space-2) var(--space-3);
        border: 1px solid var(--color-line);
        border-radius: var(--radius-2);
        background: var(--color-surface);
        color: var(--color-text);
    }

    input:focus-visible,
    select:focus-visible,
    textarea:focus-visible,
    button:focus-visible,
    a:focus-visible {
        outline: 2px solid var(--color-signal);
        outline-offset: 2px;
    }

    :root {
        color-scheme: light;
    }
}

/* ── App shell (owned by the root layout) ─────────────────────────────────── */
.shell {
    min-height: 100vh;
}

.sidebar {
    position: fixed;
    inset: 0 auto 0 0;
    width: var(--w-sidebar);
    z-index: 20;
    display: flex;
    flex-direction: column;
    background: var(--color-ink);
    color: #c6d2e6;
    border-right: 1px solid var(--color-ink-line);
}

/* the isomorphic seam — a hairline where server DOM meets client */
.sidebar::after {
    content: "";
    position: absolute;
    top: 0;
    right: -1px;
    width: 1px;
    height: 100%;
    background: linear-gradient(180deg, transparent, var(--color-signal) 20%, var(--color-live) 80%, transparent);
    opacity: 0.6;
}

.brand {
    display: flex;
    align-items: baseline;
    gap: var(--space-2);
    padding: var(--space-6) var(--space-5) var(--space-4);
    font-family: var(--font-display);
    font-weight: 700;
    font-size: var(--text-xl);
    letter-spacing: -0.02em;
    color: #fff;
}

.brand small {
    font-family: var(--font-mono);
    font-weight: 400;
    font-size: var(--text-2xs);
    letter-spacing: 0.04em;
    color: #7c8db0;
    text-transform: uppercase;
}

.index {
    overflow-y: auto;
    padding: var(--space-1) var(--space-3) var(--space-7);
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: var(--space-5);
}

.idx-group {
    display: flex;
    flex-direction: column;
    gap: 1px;
}

.idx-label {
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    font-weight: 600;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: #6f80a3;
    padding: 0 var(--space-2) var(--space-1);
}

.idx-link {
    position: relative;
    display: flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-1) var(--space-3);
    border-radius: var(--radius-2);
    color: #b9c6dd;
    font-size: var(--text-sm);
    font-weight: 450;
    text-decoration: none;
    transition: background 0.12s ease, color 0.12s ease;
}

.idx-link::before {
    content: "";
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: #3c4c68;
    flex: none;
    transition: background 0.12s ease, transform 0.12s ease;
}

.idx-link:hover {
    background: var(--color-ink-2);
    color: #eaf1ff;
    text-decoration: none;
}

.idx-link:hover::before {
    background: #5c6f96;
}

.idx-active {
    background: var(--color-ink-2);
    color: #fff;
    font-weight: 600;
}

.idx-active::before {
    background: var(--color-live);
    transform: scale(1.35);
    box-shadow: 0 0 8px color-mix(in srgb, var(--color-live) 70%, transparent);
}

.content {
    margin-left: var(--w-sidebar);
    min-height: 100vh;
}

/* THE PAGE IS TWO COLUMNS: demo cards on the left, the prose about them on the right, each paragraph
   level with the card it describes. Prose above a card reads as page text that happens to precede one —
   beside it, the connection needs no explaining. One grid does it, so a row's two halves genuinely share
   a baseline; `display: contents` on the wrappers between here and the page's own children is what lets
   the page author cards and prose as ordinary siblings and still land them in the right columns. */
.content-inner {
    display: grid;
    grid-template-columns: minmax(0, var(--w-cards)) var(--w-aside);
    align-items: start;
    gap: var(--space-6) var(--space-7);
    max-width: calc(var(--w-cards) + var(--space-7) + var(--w-aside) + 2 * var(--space-8));
    padding: var(--space-9) var(--space-8) var(--space-11);
}

.content-col,
.content-col>.page {
    display: contents;
}

/* Everything a page renders is a card unless it says otherwise — the left column is the default. */
.content-inner>*,
.page>* {
    grid-column: 1;
    min-width: 0;
}

.page>h1,
.page>.lead {
    grid-column: 1 / -1;
}

/* …and the right column is opt-in: the aside a card carries, plus the layout's own end-of-page blocks. */
.page>.aside,
.rail {
    grid-column: 2;
}

/* The prose column. Its own measure, its own rhythm — several paragraphs, a note, a list. */
.aside {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    /* The grid column already bounds it; this is for the one page whose content sits inside a nested
     layout's own box, where the aside flows under its card instead of beside it. */
    max-width: var(--w-prose);
    font-size: var(--text-sm);
    line-height: var(--leading-snug);
    color: var(--color-muted);
}

.aside p {
    font-size: inherit;
    line-height: inherit;
}

.aside> :first-child {
    margin-top: var(--space-1);
}

.aside a {
    color: var(--color-signal);
}

.aside code {
    font-size: 0.94em;
}

.aside .note {
    padding-left: var(--space-3);
    border-left: 2px solid color-mix(in srgb, var(--color-live) 55%, var(--color-line));
}

.aside .note::before {
    content: "note";
    display: block;
    margin-bottom: var(--space-1);
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    font-weight: 600;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: #8b97a8;
}

/* The layout's own right-column blocks: the page tip at the top, where to read next at the end. */
.rail {
    display: flex;
    flex-direction: column;
    gap: var(--space-5);
}

.rail-block {
    display: flex;
    flex-direction: column;
    gap: 1px;
}

.rail-label {
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    font-weight: 600;
    letter-spacing: 0.13em;
    text-transform: uppercase;
    color: #8b97a8;
}

.rail-tip {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    padding-left: var(--space-4);
    border-left: 2px solid var(--color-live);
}

.rail-tip p {
    font-size: var(--text-sm);
    line-height: var(--leading-snug);
    color: var(--color-muted);
}

.rail-tip code {
    font-size: 0.95em;
    background: #eef1f6;
}

.rail-link {
    padding: var(--space-1) 0;
    font-size: var(--text-sm);
    color: var(--color-muted);
    text-decoration: none;
    transition: color 0.12s ease;
}

.rail-link:hover {
    color: var(--color-signal);
    text-decoration: none;
}

.rail-next {
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    padding: var(--space-3) var(--space-4);
    border: 1px solid var(--color-line);
    border-radius: var(--radius-4);
    background: var(--color-surface);
    text-decoration: none;
    transition: border-color 0.12s ease, box-shadow 0.12s ease;
}

.rail-next:hover {
    border-color: color-mix(in srgb, var(--color-signal) 40%, var(--color-line));
    box-shadow: 0 4px 14px rgba(16, 24, 40, 0.07);
    text-decoration: none;
}

.rail-next-label {
    font-family: var(--font-display);
    font-weight: 500;
    color: var(--color-text);
}

.rail-next:hover .rail-next-label {
    color: var(--color-signal);
}

/* Breadcrumb — the current route as a clickable file path (a folder is a URL). */
.crumb {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0;
    font-family: var(--font-mono);
    font-size: var(--text-xs);
}

.crumb-root {
    color: #9aa6b6;
}

.crumb-sep {
    color: #c4ccd6;
    margin: 0 var(--space-2);
}

.crumb a {
    color: var(--color-muted);
    text-decoration: none;
}

.crumb a:hover {
    color: var(--color-signal);
    text-decoration: none;
}

.crumb a:last-of-type {
    color: var(--color-signal);
    font-weight: 600;
}

/* Sidebar sub-index — the samples on the OPEN page (injected client-side under the active link). */
.idx-samples {
    display: flex;
    flex-direction: column;
    gap: 1px;
    margin-left: var(--space-5);
    padding-left: var(--space-3);
    border-left: 1px solid var(--color-ink-line);
}

.idx-sample {
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-1);
    color: #8a99b6;
    font-size: var(--text-xs);
    text-decoration: none;
    transition: color 0.12s ease, background 0.12s ease;
}

.idx-sample:hover {
    color: #dce6f7;
    text-decoration: none;
}

.idx-sample-active {
    color: #fff;
    background: var(--color-ink-2);
}

/* Below this the two columns can't both hold a measure, so the grid collapses to one and every aside
   falls in under the card it belongs to — which is the order they are authored in, so nothing is lost. */
@media (max-width: 72rem) {
    .content-inner {
        grid-template-columns: minmax(0, 1fr);
    }

    .page>.aside,
    .rail {
        grid-column: 1;
    }
}

@media (max-width: 860px) {
    .sidebar {
        position: static;
        width: auto;
    }

    .content {
        margin-left: 0;
    }

    .content-inner {
        padding: var(--space-7) var(--space-5) var(--space-10);
    }
}

/* ── Page content — the semantic classes the sample pages already use ─────── */
/* In-content nav rows: the section-hub links (e.g. /platform → its sub-pages) and the per-page
   related-section links. The sidebar is the primary index; these read as secondary, in-flow links. */
.content .nav {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2) var(--space-5);
    align-items: center;
    padding-bottom: var(--space-4);
    border-bottom: 1px solid var(--color-line);
    font-size: var(--text-base);
}

.content .nav a {
    color: var(--color-muted);
    font-weight: 500;
}

.content .nav a:hover {
    color: var(--color-signal);
    text-decoration: none;
}

/* The page IS a vertical flow — one gap owns the rhythm between heading, prose, and every demo card. */
.page {
    max-width: none;
    margin: 0;
    padding: 0;
}

.lead {
    font-size: var(--text-lg);
    color: var(--color-muted);
    max-width: var(--w-prose);
}

.muted {
    color: var(--color-muted);
}

.hint {
    color: var(--color-live);
    font-weight: 500;
}

.say {
    font-size: var(--text-lg);
}

.via {
    font-family: var(--font-mono);
    font-size: var(--text-xs);
    color: var(--color-muted);
}

.row,
.controls,
.counter {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
    align-items: center;
}

.grid,
.cards,
.surfaces,
.caps {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--w-card-min), 1fr));
    gap: var(--space-4);
    list-style: none;
    padding-left: 0;
}

.list,
.chips,
.topics,
.links {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
    list-style: none;
    padding-left: 0;
}

.list {
    flex-direction: column;
}

.links {
    gap: var(--space-3);
}

.card,
.surfaces>*,
.region {
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    background: var(--color-surface);
    border: 1px solid var(--color-line);
    border-radius: var(--radius-4);
    padding: var(--space-4);
    box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
    transition: border-color 0.12s ease, box-shadow 0.12s ease, transform 0.12s ease;
}

.card:hover {
    border-color: color-mix(in srgb, var(--color-signal) 40%, var(--color-line));
    box-shadow: 0 4px 14px rgba(16, 24, 40, 0.07);
    transform: translateY(-1px);
}

.card a {
    font-family: var(--font-display);
}

/* ── Sample card — a self-contained, reproducible demo unit ────────────────── */
/* Three BANDS in reading order, each on its own ground so you never have to work out which kind of
   thing you are looking at: ABOUT (what this shows — title + description, on the header tint) · LIVE
   (the thing actually running, on white) · SOURCE (the code that produced it, dark panels on a tinted
   floor). Hairlines separate them, so the card is block flow with padded sections — not gap. */
.sample {
    border: 1px solid var(--color-line);
    border-radius: var(--radius-5);
    background: var(--color-surface);
    overflow: hidden;
    box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
    scroll-margin-top: var(--space-6);
}

.sample-about {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    padding: var(--space-4) var(--space-6);
    background: #fbfcfe;
    border-bottom: 1px solid var(--color-line);
}

.sample-about h2 {
    font-size: var(--text-lg);
}

.sample-about h2 code {
    background: #eef1f6;
}

/* The description reads at prose measure even when the card breaks out to two code columns — a demo
   title can span the card, a sentence about it should not. */
.sample-about p {
    max-width: var(--w-prose);
    color: var(--color-muted);
    font-size: var(--text-sm);
    line-height: var(--leading-snug);
}

/* The live-demo body IS a vertical flow — its `gap` spaces the controls, output, stream, etc. A panel's
   body is the same band without the LIVE strip above it, so it carries its own top padding. */
.sample-body { display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-5) var(--space-6) var(--space-6); }
.sample-body > :only-child { margin: 0; }
.sample-demo {
    display: flex;
    flex-direction: column;
    gap: var(--space-4);
    padding: var(--space-3) var(--space-6) var(--space-6);
}

/* the "run" / live strip above a demo */
.sample-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--space-3) var(--space-6) 0;
}

.sample-run {
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--color-live);
}

/* Source viewer — SERVER and CLIENT are two INDEPENDENT columns, each a code-editor file-tab strip
   fused to the code panel below it. A side holding several files tabs within its own column, so the
   pair is never a single strip you have to leave to see the other side. Fixed order: server, then
   client. The active tab shares the code panel's dark background so it visibly "opens into" the
   source it is showing; inactive tabs are muted on a lighter tab bar. */
.sample-source {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(23rem, 100%), 1fr));
    gap: var(--space-4);
    padding: var(--space-4);
    background: #f6f8fb;
    border-top: 1px solid var(--color-line);
}

/* min-width: 0 — a grid item's default `auto` minimum is its content, which a wide line of code would
   blow past, pushing the column (and the card) wider instead of scrolling inside `.code`. */
.source-col {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

/* Stacked, the card's `tab` says which side reads first; side by side (below) it has nothing to say. */
.sample-source.lead-client .source-col[data-side="client"] {
    order: -1;
}

/* `baseline`, not `flex-end`: the side label and the file tabs are set at different sizes, so aligning
   their BOXES leaves their text on two different lines. Baseline-aligning still leaves the tab flush to
   the bar's bottom edge (it is the deepest item below the shared baseline), so the active tab keeps
   fusing into the panel. */
.sample-tabs {
    display: flex;
    gap: var(--space-3);
    align-items: baseline;
    padding: var(--space-2) var(--space-3) 0;
    background: var(--color-ink-2);
    border: 1px solid var(--color-ink-line);
    border-bottom: none;
    border-radius: var(--radius-4) var(--radius-4) 0 0;
}

.tab-strip {
    display: flex;
    gap: var(--space-1);
    align-items: flex-end;
    min-width: 0;
    overflow-x: auto;
}

.tab-side {
    font-family: var(--font-mono);
    font-size: var(--text-2xs);
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #6b7aa8;
    white-space: nowrap;
}

.tab {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    cursor: pointer;
    font-family: var(--font-mono);
    font-size: var(--text-xs);
    font-weight: 500;
    white-space: nowrap;
    color: #8b98c4;
    background: transparent;
    border: none;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-2) var(--radius-2) 0 0;
    transition: background 0.12s ease, color 0.12s ease;
}

.tab:hover {
    color: #d6e2ff;
    background: color-mix(in srgb, var(--color-ink) 55%, transparent);
}

.tab.active {
    color: #82aaff;
    background: var(--color-ink);
}

.sample-panels {
    flex: 1;
    min-width: 0;
}

.tab-panel {
    display: none;
    height: 100%;
}

.tab-panel.active {
    display: block;
}

.tab-panel .code,
.sample-panels > .code {
    height: 100%;
    border-radius: 0 0 var(--radius-4) var(--radius-4);
}

/* Side by side whenever two code measures actually FIT — asked of the card, not of the viewport. The
   card is its own column now, so there is nothing to break out of and nothing to derive from `100vw`:
   `auto-fit` splits the pair when each side clears its minimum and stacks them when it doesn't. */

.pill,
.badge {
    display: inline-flex;
    align-items: center;
    gap: var(--space-1);
    font-family: var(--font-mono);
    font-size: var(--text-xs);
    font-weight: 500;
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-pill);
    background: var(--color-signal-soft);
    color: var(--color-signal);
    border: 1px solid #d7e0ff;
}

.badge {
    font-family: var(--font-sans);
}

.err {
    color: #d1435b;
    font-weight: 500;
}

/* live output / stream / socket log — spaced by their flex-container's gap, never their own margin */
.out,
.log,
.stream {
    font-family: var(--font-mono);
    font-size: var(--text-sm);
    line-height: var(--leading-code);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-3);
    background: var(--color-ink);
    color: #cfe0ff;
    overflow-x: auto;
    border: 1px solid var(--color-ink-line);
}

.log {
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
}

.msg {
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-1);
}

.msg[data-via="server"] {
    background: color-mix(in srgb, var(--color-signal) 16%, transparent);
}

.msg[data-via="client"] {
    background: color-mix(in srgb, var(--color-live) 16%, transparent);
}

.empty {
    color: color-mix(in srgb, #cfe0ff 55%, transparent);
    font-style: italic;
}

/* route() readout — a definition list of the current route */
.route {
    display: grid;
    grid-template-columns: max-content 1fr;
    gap: var(--space-1) var(--space-4);
    font-family: var(--font-mono);
    font-size: var(--text-sm);
}

.route dt {
    color: var(--color-signal);
    font-weight: 600;
}

.route dd {
    margin: 0;
    color: var(--color-text);
}

/* source caption + loading (the {source(...)} demo blocks) */
.src-cap {
    font-family: var(--font-mono);
    font-size: var(--text-xs);
    color: var(--color-muted);
}

.src-loading {
    color: var(--color-muted);
    font-style: italic;
}

/* Code block theme — pairs with codeBlock()/highlight() token classes. */
.code {
    padding: var(--space-4);
    border-radius: var(--radius-4);
    background: var(--color-ink);
    color: #d6e2ff;
    overflow-x: auto;
    font-family: var(--font-mono);
    font-size: var(--text-sm);
    line-height: var(--leading-normal);
    tab-size: 2;
    border: 1px solid var(--color-ink-line);
}

.code code {
    font: inherit;
    white-space: pre;
    background: none;
    border: none;
    padding: 0;
    color: inherit;
}

.tok-keyword {
    color: #c792ea;
}

.tok-string {
    color: #c3e88d;
}

.tok-comment {
    color: #7686b3;
    font-style: italic;
}

.tok-number {
    color: #f78c6c;
}

.tok-fn {
    color: #82aaff;
}

.tok-tag {
    color: #f07178;
}

.tok-attr {
    color: #ffcb6b;
}

.tok-brace {
    color: #89ddff;
}

.tok-block {
    color: #c792ea;
    font-weight: 600;
}

.tok-punct {
    color: #8b98c4;
}

.caps>li {
    background: var(--color-surface);
    border: 1px solid var(--color-line);
    border-radius: var(--radius-4);
    padding: var(--space-3) var(--space-4);
}

/* class:highlight demo — the toggled state */
.highlight {
    background: #fff3bf;
    box-shadow: inset 0 0 0 1px #ffe066;
    border-radius: var(--radius-1);
}

/* demo-local elements used inside sample markup */
.card-body {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    color: var(--color-text);
}

.chip {
    display: inline-flex;
    align-items: center;
    padding: var(--space-1) var(--space-3);
    background: var(--color-signal-soft);
    color: var(--color-signal);
    border: 1px solid #d7e0ff;
    border-radius: var(--radius-pill);
    font-size: var(--text-sm);
    font-weight: 500;
}

.framed {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    padding: var(--space-3) var(--space-4);
    border: 1px dashed color-mix(in srgb, var(--color-signal) 45%, var(--color-line));
    border-radius: var(--radius-3);
    background: #fbfcff;
}

.raw {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    padding: var(--space-3) var(--space-4);
    background: var(--color-ink);
    color: #d6e2ff;
    border-radius: var(--radius-3);
    border: 1px solid var(--color-ink-line);
}

